/**
 * Fact-audit fix pass, Round 2, group B_mixguides (2026-10-22): Computer B's
 * fact-check return for the 50 mixing guides. Pins a sample of the fixes
 * (new wording present, wrong wording gone), the ONE shared WHO hearing note
 * (owner ruling 3) and a small ratchet on the loudness table cells.
 *
 * The guide files are generated by scripts/mixing-guides/; these edits were
 * made in the guide files directly and are listed in the round's ledger
 * (`generated: true`) so the converter can mirror them.
 */
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, it } from 'node:test';

const ROOT = join(import.meta.dirname, '..');
const read = (rel: string) => readFileSync(join(ROOT, rel), 'utf8').replace(/\r\n/g, '\n');
const DIR = 'src/screens/lab/mixingGuides/data/guides';
const g = (name: string) => read(`${DIR}/${name}.ts`);

describe('fact audit R2 · mixing guides: fixed claims', () => {
  it('EDM: the 60-minute cap pairs with a 125 dBA maximum, not 115', () => {
    const s = g('g05-edm-festival-electronic');
    assert.match(s, /100 dBA over 60 min with a 125 dBA maximum in others/);
    assert.doesNotMatch(s, /115 dBA peak in others/);
  });
  it('country: a −9 to −7 LUFS-I master takes −2 dBTP (prose and table)', () => {
    const s = g('g06-country');
    assert.match(s, /louder than −14 LUFS, a common streaming recommendation puts true peak at or below −2 dBTP/);
    assert.match(s, /"−9 to −7 LUFS-I \(modern\), −2 dBTP"/);
    assert.doesNotMatch(s, /−9 to −7 LUFS-I \(modern\), −1 dBTP/);
  });
  it('reggaeton, metal, D&B, funk BR: PLR matches the stated loudness range', () => {
    assert.match(g('g08-reggaeton'), /a −8 to −5 LUFS-I master leaves only 3–6 dB/);
    assert.doesNotMatch(g('g08-reggaeton'), /low PLR \(6–9 dB/);
    assert.match(g('g19-heavy-metal'), /PLR \(peak minus loudness\) of only about 3–6 dB/);
    assert.doesNotMatch(g('g19-heavy-metal'), /PLR as low as 6–8 dB/);
    assert.match(g('g45-drum-and-bass'), /a −7 to −5 LUFS-I master leaves only 3–5 dB/);
    assert.match(g('g35-brazilian-funk'), /a −7 to −4 LUFS-I master leaves only 2–5 dB/);
  });
  it('blues: the 11–15 dB PLR is for traditional masters only', () => {
    const s = g('g31-blues');
    assert.match(s, /For traditional masters, aim for a PLR of 11–15 dB/);
    assert.match(s, /[Ll]ouder electric masters land nearer 7–9 dB/);
  });
  it('classical: largo at 40 BPM, harp is not percussion, no wrong 5–7 dB gap', () => {
    const s = g('g15-classical-orchestral');
    assert.match(s, /from about 40 \(largo\)/);
    assert.doesNotMatch(s, /40 \(adagio\)/);
    assert.doesNotMatch(s, /mallets and harp/);
    assert.match(s, /The harp \(a plucked string\) often sits nearby/);
    assert.doesNotMatch(s, /5–7 dB louder/);
  });
  it('sertanejo: Barretos arena about 35,000 seats; violão glossed as acoustic guitar', () => {
    const s = g('g29-sertanejo');
    assert.match(s, /a rodeo arena with about 35,000 seats/);
    assert.doesNotMatch(s, /80,000-capacity/);
    assert.doesNotMatch(s, /far higher rate than any other market/);
    assert.doesNotMatch(s, /violão \(nylon-string guitar\)/);
  });
  it('bhangra went on stage in the 1950s (guide and index)', () => {
    for (const s of [g('g30-punjabi-pop-bhangra'), read('src/screens/lab/mixingGuides/data/index.ts')]) {
      assert.match(s, /staged bhangra from the 1950s/);
      assert.doesNotMatch(s, /staged bhangra from the 1960s–70s/);
    }
  });
  it('crest factor, bongos, reggae bass band, lo-fi gain, Hamilton, Larry Graham', () => {
    assert.match(g('g35-brazilian-funk'), /a very low crest factor \(only a few dB\)/);
    assert.doesNotMatch(g('g35-brazilian-funk'), /near-zero crest factor/);
    assert.match(g('g39-bachata'), /Bongos are already bright and high-pitched/);
    assert.match(g('g28-reggae'), /the midrange lift helps small speakers/);
    assert.match(g('g46-lo-fi-chillhop'), /set the texture level at the source or on its own track/);
    assert.doesNotMatch(g('g46-lo-fi-chillhop'), /manage with input gain/);
    assert.match(g('g48-musical-theatre'), /\(Rock of Ages, Six\)/);
    assert.match(g('g32-funk'), /Larry Graham in the mid-1960s/);
  });
  it('East Java 2025 caps are A-weighted (three places)', () => {
    const s = g('g43-dangdut');
    assert.match(s, /stationary systems at 120 dBA and moving units at 85 dBA/);
    assert.match(s, /static systems at 120 dBA \(2025 rule\)/);
    assert.match(s, /120 dBA East Java static systems/);
    assert.doesNotMatch(s, /120 dB(?![AC])/); // Round A 2026-10-23: "112–120 dBC LCeq" is the C-weighted show level, not a cap
  });
  it('a dotted 1/8 is the same note as 3/16', () => {
    assert.match(g('g45-drum-and-bass'), /Dotted 1\/8 \(same as 3\/16\) at 174 BPM/);
    assert.match(g('g33-techno'), /Dotted 1\/8 \(same as 3\/16\)/);
  });
});

describe('fact audit R2 · mixing guides: the ONE WHO hearing note (owner ruling 3)', () => {
  const NOTE = 'WHO recommends audiences be exposed to no more than 100 dB LAeq over 15 minutes — protect your hearing.';
  it('is one shared constant, rendered under the live level', () => {
    const types = read('src/screens/lab/mixingGuides/data/types.ts');
    assert.ok(types.includes(`WHO_LIVE_LEVEL_NOTE =\n  '${NOTE}'`));
    const screen = read('src/screens/lab/mixingGuides/MixingGuideScreen.tsx');
    assert.match(screen, /r\.key === 'liveSpl' \? <Text style=\{styles\.glanceNote\}>\{WHO_LIVE_LEVEL_NOTE\}<\/Text>/);
  });
  it('is not copied into the guide files', () => {
    for (const f of readdirSync(join(ROOT, DIR))) {
      assert.ok(!read(`${DIR}/${f}`).includes('WHO recommends audiences'), `${f} carries its own copy of the WHO note`);
    }
  });
});

describe('fact audit R2 · mixing guides: loudness table ratchet', () => {
  it('no table cell pairs a master louder than −14 LUFS with a bare −1 dBTP', () => {
    const offenders: string[] = [];
    for (const f of readdirSync(join(ROOT, DIR))) {
      for (const m of read(`${DIR}/${f}`).matchAll(/"(−(\d+) to −(\d+) LUFS-I[^"]*?), −1 dBTP(?! \()[^"]*"/g)) {
        // The quieter bound is the first number; a range wholly louder than −14 needs −2 dBTP.
        if (Number(m[2]) < 14) offenders.push(`${f}: ${m[0]}`);
      }
    }
    assert.deepEqual(offenders, []);
  });
});
